const { io } = require('socket.io-client');
const { ipcRenderer } = require('electron');
const crypto = require('crypto');

const $ = id => document.getElementById(id);
const els = {
  setup:$('setup'),app:$('app'),setupName:$('setupName'),setupInvite:$('setupInvite'),setupUrl:$('setupUrl'),connectBtn:$('connectBtn'),hostBtn:$('hostBtn'),hostProgress:$('hostProgress'),
  homeServer:$('homeServer'),dmUnreadBadge:$('dmUnreadBadge'),serverList:$('serverList'),addServerBtn:$('addServerBtn'),serverName:$('serverName'),inviteBtn:$('inviteBtn'),serverSettingsBtn:$('serverSettingsBtn'),channels:$('channels'),
  myAvatar:$('myAvatar'),myName:$('myName'),myStatusText:$('myStatusText'),ping:$('ping'),profileBtn:$('profileBtn'),memberList:$('memberList'),
  channelIcon:$('channelIcon'),channelName:$('channelName'),channelDesc:$('channelDesc'),connectionBadge:$('connectionBadge'),updateBadge:$('updateBadge'),emptyView:$('emptyView'),textView:$('textView'),voiceView:$('voiceView'),
  messages:$('messages'),messageForm:$('messageForm'),messageInput:$('messageInput'),voiceTitle:$('voiceTitle'),voiceSubtitle:$('voiceSubtitle'),joinVoiceBtn:$('joinVoiceBtn'),videoGrid:$('videoGrid'),
  reconnectVoiceBtn:$('reconnectVoiceBtn'),hideCamsBtn:$('hideCamsBtn'),voiceControls:$('voiceControls'),voiceChannelName:$('voiceChannelName'),muteBtn:$('muteBtn'),deafenBtn:$('deafenBtn'),cameraBtn:$('cameraBtn'),screenBtn:$('screenBtn'),hangupBtn:$('hangupBtn'),
  modal:$('modal'),modalBody:$('modalBody'),modalClose:$('modalClose'),toast:$('toast')
};

const ROLE_RANK={member:0,moderator:1,admin:2,owner:3};
const ROLE_LABEL={owner:'Dono',admin:'Administrador',moderator:'Moderador',member:'Membro'};
const STATUS_LABEL={online:'Online',busy:'Ocupado',away:'Ausente',offline:'Offline'};
const ls=(key,def='')=>localStorage.getItem(`banana.${key}`)??def;
const bool=(key,def=false)=>{const v=localStorage.getItem(`banana.${key}`);return v==null?def:v==='true'};
const num=(key,def)=>{const v=Number(localStorage.getItem(`banana.${key}`));return Number.isFinite(v)?v:def};
let peerVolumes={};try{peerVolumes=JSON.parse(ls('peerVolumes','{}'))||{}}catch{}

const state={
  socket:null,readyOnce:false,
  deviceId:ls('deviceId')||crypto.randomUUID(),
  user:null,servers:[],selectedServer:null,selectedChannel:null,members:new Map(),messagesByChannel:new Map(),voicePresence:new Map(),viewMode:'server',activeDmUserId:null,dmConversations:[],dmMessages:new Map(),dmUnread:new Set(),
  serverUrl:'',pendingInvite:'',isHost:false,publicHostUrl:'',
  media:{
    micId:ls('micId'),speakerId:ls('speakerId'),cameraId:ls('cameraId'),outputVolume:num('outputVolume',1),peerVolumes,
    echoCancellation:bool('echoCancellation',true),noiseSuppression:bool('noiseSuppression',true),autoGainControl:bool('autoGainControl',true),voiceThreshold:num('voiceThreshold',14),autoMute:bool('autoMute',false),
    cameraQuality:ls('cameraQuality','720'),cameraFps:num('cameraFps',30),screenQuality:ls('screenQuality','1080'),screenFps:num('screenFps',60),streamPreset:ls('streamPreset','auto')
  },
  ui:{
    status:ls('status','online'),joinLeaveSounds:bool('joinLeaveSounds',true),autoFocusShare:bool('autoFocusShare',true),showStats:bool('showStats',true),
    pttEnabled:bool('pttEnabled',false),pttKey:ls('pttKey','KeyV'),focusSharing:false,showAllOverride:false
  },
  updates:{config:{repoUrl:'',autoCheck:true,autoDownload:true,currentVersion:'0.10.0'},state:{status:'idle',progress:0,message:''}},
  voice:{channelId:null,serverId:null,localAudio:null,camera:null,screen:null,muted:false,deafened:false,speaking:false,pttHeld:false,peers:new Map(),statsTimer:null,vad:null,rejoinTimer:null}
};
localStorage.setItem('banana.deviceId',state.deviceId);
els.setupName.value=ls('name');els.setupUrl.value=ls('serverUrl','http://localhost:3210');

function toast(msg,ms=2800){els.toast.textContent=String(msg||'');els.toast.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>els.toast.classList.add('hidden'),ms)}
function openModal(html){els.modal.querySelector('.modal-card')?.classList.remove('settings-modal');els.modalBody.innerHTML=html;els.modal.classList.remove('hidden')}
function closeModal(){stopMicTest();stopCameraTest();els.modal.classList.add('hidden');els.modalBody.innerHTML=''}
els.modalClose.addEventListener('click',closeModal);els.modal.addEventListener('click',e=>{if(e.target===els.modal)closeModal()});
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtTime(ts){return new Date(ts).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}
function avatarStyle(el,user){if(!el)return;el.style.backgroundImage='';el.textContent=(user?.name||'?').trim().slice(0,1).toUpperCase();if(user?.avatar){el.style.backgroundImage=`url(${user.avatar})`;el.textContent=''}}
function roleFor(userId,stateServer=state.selectedServer){if(!stateServer||!userId)return'member';if(stateServer.ownerId===userId)return'owner';return stateServer.memberRoles?.[userId]||'member'}
function currentRole(){return roleFor(state.user?.id)}
function can(min){return (ROLE_RANK[currentRole()]||0)>=(ROLE_RANK[min]||0)}
function renderSelf(){els.myName.textContent=state.user?.name||'Usuário';avatarStyle(els.myAvatar,state.user);els.myStatusText.textContent=STATUS_LABEL[state.user?.status||state.ui.status]||'Online'}
function setConnection(ok){els.connectionBadge.textContent=ok?'conectado':'offline';els.connectionBadge.classList.toggle('offline',!ok)}
function parseInvite(raw){const v=String(raw||'').trim();if(!v)return null;if(v.startsWith('BANANA|')){const p=v.split('|');if(p.length>=3)return{url:p[1],code:p[2],updateRepo:p[3]||''}}if(/^https?:\/\//i.test(v))return{url:v.replace(/\/$/,''),code:'',updateRepo:''};return null}
function makeInvite(url,code){const repo=String(state.updates.config?.repoUrl||'').trim();return`BANANA|${url}|${code}${repo?`|${repo}`:''}`}
function validGithubRepo(v){try{const u=new URL(String(v||''));const parts=u.pathname.split('/').filter(Boolean);return ['github.com','www.github.com'].includes(u.hostname.toLowerCase())&&parts.length>=2}catch{return false}}
function savePrefs(){
  const media={micId:state.media.micId,speakerId:state.media.speakerId,cameraId:state.media.cameraId,outputVolume:state.media.outputVolume,peerVolumes:JSON.stringify(state.media.peerVolumes||{}),echoCancellation:state.media.echoCancellation,noiseSuppression:state.media.noiseSuppression,autoGainControl:state.media.autoGainControl,voiceThreshold:state.media.voiceThreshold,autoMute:state.media.autoMute,cameraQuality:state.media.cameraQuality,cameraFps:state.media.cameraFps,screenQuality:state.media.screenQuality,screenFps:state.media.screenFps,streamPreset:state.media.streamPreset};
  const ui={status:state.ui.status,joinLeaveSounds:state.ui.joinLeaveSounds,autoFocusShare:state.ui.autoFocusShare,showStats:state.ui.showStats,pttEnabled:state.ui.pttEnabled,pttKey:state.ui.pttKey};
  for(const [k,v]of Object.entries({...media,...ui}))localStorage.setItem(`banana.${k}`,String(v));
}

els.hostBtn.addEventListener('click',hostBananaCord);els.connectBtn.addEventListener('click',connectFromSetup);els.setupInvite.addEventListener('keydown',e=>{if(e.key==='Enter')connectFromSetup()});
ipcRenderer.on('host:status',(_e,data)=>{els.hostProgress.classList.remove('hidden');const map={starting:'Iniciando o servidor…',downloading:'Preparando o acesso pela internet…',tunneling:'Abrindo acesso seguro pela internet…','local-ready':'Servidor local pronto…',ready:'Seu Banana Cord está online.',stopped:'Servidor encerrado.','tunnel-ended':'O acesso pela internet foi encerrado.'};els.hostProgress.textContent=data.message||map[data.status]||data.status});
ipcRenderer.on('shortcut:mute',()=>toggleMute());ipcRenderer.on('shortcut:deafen',()=>toggleDeafen());ipcRenderer.on('shortcut:screen',()=>toggleScreen());
ipcRenderer.on('update:state',(_e,data)=>handleUpdateState(data||{}));
async function loadUpdateConfig(){try{state.updates.config=await ipcRenderer.invoke('update:get-config');state.updates.state=await ipcRenderer.invoke('update:get-state')}catch{}handleUpdateState(state.updates.state)}
function handleUpdateState(data={}){state.updates.state={...state.updates.state,...data};if(data.repoUrl!=null)state.updates.config={...state.updates.config,repoUrl:data.repoUrl,autoCheck:data.autoCheck!==false,autoDownload:data.autoDownload!==false,currentVersion:data.currentVersion||state.updates.config.currentVersion};const st=state.updates.state.status||'idle';if(els.updateBadge){const show=['available','downloading','downloaded','error'].includes(st);els.updateBadge.classList.toggle('hidden',!show);els.updateBadge.textContent=st==='downloaded'?'↻ Reiniciar e atualizar':st==='downloading'?`⬇ ${Math.round(Number(state.updates.state.progress||0))}%`:st==='error'?'⚠ Atualização':'⬇ Atualização';els.updateBadge.classList.toggle('ready',st==='downloaded')}if(st==='downloaded'&&!handleUpdateState._notified){handleUpdateState._notified=true;toast('Banana Cord atualizado e pronto para instalar ao reiniciar.',5000)}}
async function maybeAdoptUpdateRepo(repo){const incoming=String(repo||'').trim();if(!validGithubRepo(incoming))return;const current=String(state.updates.config?.repoUrl||'').trim();if(current===incoming)return;if(!confirm(`Este convite recomenda receber atualizações de:\n${incoming}\n\nAceitar essa fonte de atualizações?`))return;try{state.updates.config=await ipcRenderer.invoke('update:save-config',{...state.updates.config,repoUrl:incoming});toast('Fonte de atualizações configurada.')}catch(e){toast(e?.message||'Não consegui configurar atualizações.',4000)}}

async function hostBananaCord(){const name=els.setupName.value.trim();if(!name)return toast('Digite seu nome primeiro.');els.hostBtn.disabled=true;els.connectBtn.disabled=true;els.hostProgress.classList.remove('hidden');els.hostProgress.textContent='Iniciando o Banana Cord…';try{const info=await ipcRenderer.invoke('host:start');state.isHost=true;state.publicHostUrl=info.url||info.localUrl;els.setupUrl.value=info.localUrl||'http://127.0.0.1:3210';connectTo(info.localUrl||'http://127.0.0.1:3210',name,'')}catch(e){toast(e?.message||'Não consegui hospedar o Banana Cord.',5000);els.hostBtn.disabled=false;els.connectBtn.disabled=false}}
async function connectFromSetup(){const name=els.setupName.value.trim();if(!name)return toast('Digite seu nome.');const parsed=parseInvite(els.setupInvite.value);let url,code='';if(parsed){url=parsed.url;code=parsed.code;if(parsed.updateRepo)await maybeAdoptUpdateRepo(parsed.updateRepo)}else url=els.setupUrl.value.trim().replace(/\/$/,'');if(!/^https?:\/\//i.test(url||''))return toast('Cole um convite válido ou informe o endereço do servidor.');connectTo(url,name,code)}
function connectTo(url,name,pendingInvite=''){localStorage.setItem('banana.name',name);localStorage.setItem('banana.serverUrl',url);state.serverUrl=url;state.pendingInvite=pendingInvite;els.hostBtn.disabled=true;els.connectBtn.disabled=true;els.connectBtn.textContent='Conectando…';state.socket?.disconnect();const socket=io(url,{transports:['websocket','polling'],reconnection:true,reconnectionAttempts:Infinity,reconnectionDelay:700,reconnectionDelayMax:4000,timeout:10000});state.socket=socket;socket.on('connect',()=>{setConnection(true);socket.emit('auth:hello',{deviceId:state.deviceId,name,avatar:ls('avatar'),status:state.ui.status})});socket.on('disconnect',()=>setConnection(false));socket.on('connect_error',()=>{setConnection(false);els.hostBtn.disabled=false;els.connectBtn.disabled=false;els.connectBtn.textContent='Entrar no Banana Cord';toast('Não consegui conectar. Verifique se o host está com o Banana Cord aberto.',4000)});bindSocket(socket)}

function bindSocket(socket){
  socket.on('auth:ready',async data=>{
    const wasReady=state.readyOnce;state.readyOnce=true;state.user=data.user;state.servers=data.servers||[];els.setup.classList.add('hidden');els.app.classList.remove('hidden');els.hostBtn.disabled=false;els.connectBtn.disabled=false;els.connectBtn.textContent='Entrar no Banana Cord';renderSelf();renderServers();startPing();socket.emit('dm:conversations:get');
    if(state.pendingInvite){const code=state.pendingInvite;state.pendingInvite='';socket.emit('server:join',{inviteCode:code})}
    else if(!state.selectedServer&&state.servers[0])selectServer(state.servers[0].id);else if(state.selectedServer){state.selectedServer=state.servers.find(s=>s.id===state.selectedServer.id)||state.servers[0]||null;if(state.selectedServer){renderChannels();socket.emit('members:get',{serverId:state.selectedServer.id})}}
    else if(!state.servers[0])showEmpty();
    if(wasReady&&state.voice.channelId&&state.voice.localAudio)await rejoinVoiceTransport();
  });
  socket.on('app:error',m=>toast(m,4200));
  socket.on('profile:updated',u=>{state.user=u;localStorage.setItem('banana.name',u.name);localStorage.setItem('banana.avatar',u.avatar||'');state.ui.status=u.status||state.ui.status;savePrefs();renderSelf();renderMembers();renderChannels()});
  socket.on('server:created',s=>{upsertServer(s);renderServers();selectServer(s.id);closeModal();toast(`Servidor ${s.name} criado.`)});
  socket.on('server:joined',s=>{upsertServer(s);renderServers();selectServer(s.id);closeModal();toast(`Você entrou em ${s.name}.`)});
  socket.on('server:removed',({serverId})=>{state.servers=state.servers.filter(s=>s.id!==serverId);if(state.selectedServer?.id===serverId){state.selectedServer=null;showEmpty()}renderServers();toast('Você foi removido desse servidor.')});
  socket.on('server:updated',s=>{upsertServer(s);if(state.selectedServer?.id===s.id){state.selectedServer=s;els.serverName.textContent=s.name;renderChannels();renderMembers()}renderServers()});
  socket.on('members:list',({serverId,members})=>{if(state.selectedServer?.id!==serverId)return;state.members=new Map((members||[]).map(m=>[m.id,m]));renderMembers();renderMessages();renderChannels()});
  socket.on('presence:update',u=>{let changed=false;if(state.members.has(u.id)){const old=state.members.get(u.id);state.members.set(u.id,{...old,...u});changed=true}const conv=state.dmConversations.find(c=>c.user?.id===u.id);if(conv){conv.user={...conv.user,...u};changed=true}if(changed){updatePresenceUser(u);renderMembers();if(state.viewMode==='dm'){renderDmSidebar();if(state.activeDmUserId===u.id)renderDmMessages()}else{renderMessages();renderChannels()}}});
  socket.on('voice:snapshot',({serverId,entries})=>{if(state.selectedServer?.id!==serverId)return;state.voicePresence=new Map();for(const e of entries||[]){const arr=state.voicePresence.get(e.channelId)||[];arr.push(e);state.voicePresence.set(e.channelId,arr)}renderChannels()});
  socket.on('voice:speaking-global',({socketId,userId,channelId,speaking})=>{const arr=state.voicePresence.get(channelId)||[];const e=arr.find(x=>x.socketId===socketId||x.user?.id===userId);if(e)e.speaking=!!speaking;renderChannels()});
  socket.on('voice:media-state-global',({socketId,userId,channelId,mediaState})=>{const arr=state.voicePresence.get(channelId)||[];const e=arr.find(x=>x.socketId===socketId||x.user?.id===userId);if(e)e.mediaState={...e.mediaState,...mediaState};renderChannels()});
  socket.on('voice:presence-event',({type,userId,channelId})=>{if(userId===state.user?.id)return;if(state.voice.channelId===channelId&&state.ui.joinLeaveSounds)playEventTone(type)});
  socket.on('messages:list',({channelId,messages})=>{state.messagesByChannel.set(channelId,messages||[]);if(state.selectedChannel?.id===channelId)renderMessages()});
  socket.on('message:new',m=>{const arr=state.messagesByChannel.get(m.channelId)||[];arr.push(m);state.messagesByChannel.set(m.channelId,arr.slice(-150));if(state.selectedChannel?.id===m.channelId)renderMessages(true)});
  socket.on('dm:conversations',({conversations})=>{state.dmConversations=Array.isArray(conversations)?conversations:[];if(state.viewMode==='dm')renderDmSidebar();updateDmUnreadBadge()});
  socket.on('dm:list',({user,messages})=>{if(!user?.id)return;mergeDmConversation(user,null);state.dmMessages.set(user.id,Array.isArray(messages)?messages:[]);if(state.viewMode==='dm'&&state.activeDmUserId===user.id)renderDmMessages(true)});
  socket.on('dm:new',({message,from,to})=>{if(!message)return;const me=state.user?.id;const peer=message.fromId===me?to:from;const peerId=peer?.id||(message.fromId===me?message.toId:message.fromId);if(!peerId)return;const arr=state.dmMessages.get(peerId)||[];if(!arr.some(x=>x.id===message.id))arr.push(message);state.dmMessages.set(peerId,arr.slice(-200));mergeDmConversation(peer||{id:peerId,name:'Amigo'},message);const open=state.viewMode==='dm'&&state.activeDmUserId===peerId;if(!open&&message.fromId!==me){state.dmUnread.add(peerId);toast(`Nova mensagem de ${peer?.name||'um amigo'}.`,3200)}else if(open){state.dmUnread.delete(peerId)}updateDmUnreadBadge();if(state.viewMode==='dm'){renderDmSidebar();if(open)renderDmMessages(true)}});
  socket.on('voice:full',()=>{cleanupVoice();toast('Essa sala já está com 5 pessoas.')});
  socket.on('voice:peers',async({channelId,peers})=>{if(state.voice.channelId!==channelId)return;for(const p of peers)await createPeer(p.socketId,p.user,true,p.mediaState||{});updateVoiceUI();startPeerStats();emitMediaState()});
  socket.on('voice:user-joined',async({socketId,user,mediaState})=>{if(state.voice.channelId&&!state.voice.peers.has(socketId))await createPeer(socketId,user,false,mediaState||{});updateVoiceUI();emitMediaState()});
  socket.on('voice:user-left',({socketId})=>removePeer(socketId));
  socket.on('voice:media-state',({socketId,mediaState})=>updatePeerMediaState(socketId,mediaState||{}));
  socket.on('voice:speaking',({socketId,speaking})=>{const p=state.voice.peers.get(socketId);if(!p)return;p.speaking=!!speaking;setCardSpeaking(`video-${socketId}`,p.speaking&&!p.mediaState?.muted)});
  socket.on('webrtc:signal',async({fromSocketId,fromUser,data})=>handleSignal(fromSocketId,fromUser,data));
}

function updatePresenceUser(u){for(const arr of state.voicePresence.values())for(const e of arr)if(e.user?.id===u.id)e.user={...e.user,...u};for(const p of state.voice.peers.values())if(p.user?.id===u.id){p.user={...p.user,...u};addRemoteCard(p)}}
function upsertServer(s){const i=state.servers.findIndex(x=>x.id===s.id);if(i>=0)state.servers[i]=s;else state.servers.push(s)}
function showEmpty(){state.selectedServer=null;state.selectedChannel=null;state.viewMode='server';state.activeDmUserId=null;els.app.classList.remove('dm-mode');els.serverName.textContent='Banana Cord';els.channels.innerHTML='';els.memberList.innerHTML='';els.emptyView.innerHTML='<div class="big-banana">🍌</div><h2>Banana Cord</h2><p>Crie ou entre em um servidor pelo botão +.</p>';els.emptyView.classList.remove('hidden');els.textView.classList.add('hidden');els.voiceView.classList.add('hidden');els.inviteBtn.style.visibility='hidden';els.serverSettingsBtn.style.visibility='hidden';renderServers()}
function renderServers(){els.homeServer?.classList.toggle('active',state.viewMode==='dm');els.serverList.innerHTML='';for(const s of state.servers){const b=document.createElement('button');b.className='server-icon'+(state.viewMode==='server'&&state.selectedServer?.id===s.id?' active':'');b.title=s.name;b.textContent=s.name.trim().slice(0,2).toUpperCase();b.addEventListener('click',()=>selectServer(s.id));els.serverList.appendChild(b)}}
function selectServer(id){if(state.voice.serverId&&state.voice.serverId!==id)leaveVoice();const s=state.servers.find(x=>x.id===id);if(!s)return;state.viewMode='server';state.activeDmUserId=null;els.app.classList.remove('dm-mode');state.selectedServer=s;els.serverName.textContent=s.name;els.inviteBtn.style.visibility='visible';els.serverSettingsBtn.style.visibility='visible';state.voicePresence=new Map();renderServers();renderChannels();state.socket.emit('members:get',{serverId:s.id});const firstText=s.channels.find(c=>c.type==='text');if(firstText)selectChannel(firstText.id);else{els.emptyView.classList.remove('hidden');els.textView.classList.add('hidden');els.voiceView.classList.add('hidden')}}

function renderChannels(){
  const s=state.selectedServer;els.channels.innerHTML='';if(!s)return;const manage=can('moderator');
  for(const type of ['text','voice']){
    const wrap=document.createElement('div');wrap.className='channel-section';const title=document.createElement('div');title.className='channel-section-title';title.innerHTML=`<span>${type==='text'?'Canais de texto':'Canais de voz'}</span>`;
    if(manage){const plus=document.createElement('button');plus.className='channel-add';plus.textContent='+';plus.title='Criar canal';plus.addEventListener('click',()=>channelModal(type));title.appendChild(plus)}wrap.appendChild(title);
    for(const c of s.channels.filter(x=>x.type===type)){
      const row=document.createElement('div');row.className='channel-row';row.dataset.channelId=c.id;row.draggable=manage;
      const b=document.createElement('button');b.className='channel'+(state.selectedChannel?.id===c.id?' active':'');b.innerHTML=`<span class="symbol">${type==='text'?'#':'🔊'}</span><span>${escapeHtml(c.name)}</span>`;b.addEventListener('click',()=>selectChannel(c.id));row.appendChild(b);
      if(manage){const actions=document.createElement('div');actions.className='channel-actions';const more=document.createElement('button');more.className='channel-more';more.title='Editar canal';more.textContent='⋯';more.addEventListener('click',e=>{e.stopPropagation();editChannelModal(c)});actions.appendChild(more);row.appendChild(actions);wireChannelDrag(row,c)}
      wrap.appendChild(row);
      if(type==='voice')renderVoiceUsers(wrap,c.id);
    }
    els.channels.appendChild(wrap);
  }
}
function wireChannelDrag(row,c){row.addEventListener('dragstart',e=>{row.classList.add('dragging');e.dataTransfer.setData('text/plain',c.id);e.dataTransfer.effectAllowed='move'});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('drag-over')});row.addEventListener('dragleave',()=>row.classList.remove('drag-over'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drag-over');const from=e.dataTransfer.getData('text/plain');if(from&&from!==c.id)state.socket.emit('channel:reorder',{serverId:state.selectedServer.id,channelId:from,beforeId:c.id})})}
function renderVoiceUsers(wrap,channelId){const entries=state.voicePresence.get(channelId)||[];if(!entries.length)return;const list=document.createElement('div');list.className='voice-user-list';for(const e of entries){const u=e.user||{name:'Amigo'};const row=document.createElement('div');row.className='voice-user-row'+(e.speaking&&!e.mediaState?.muted?' speaking':'')+(u.id===state.user?.id?' self':'');const av=document.createElement('div');av.className='avatar';avatarStyle(av,u);const nm=document.createElement('span');nm.className='voice-user-name';nm.textContent=u.name;const icons=document.createElement('span');icons.className='voice-user-icons';const peer=e.socketId?state.voice.peers.get(e.socketId):null;const latency=peer?.rtt!=null?`${peer.rtt}ms`:u.id===state.user?.id?(els.ping.textContent||''):'';icons.textContent=`${e.mediaState?.muted?'🔇':''}${e.mediaState?.camera?'📹':''}${e.mediaState?.screen?'🖥️':''}${latency?` · ${latency}`:''}`;row.append(av,nm,icons);row.title=`${u.name}${e.speaking?' está falando':''}`;row.addEventListener('click',()=>openMemberProfile(u.id));list.appendChild(row)}wrap.appendChild(list)}
function selectChannel(id){const c=state.selectedServer?.channels.find(x=>x.id===id);if(!c)return;state.selectedChannel=c;els.emptyView.classList.add('hidden');renderChannels();els.channelName.textContent=c.name;if(c.type==='text'){els.channelIcon.textContent='#';els.channelDesc.textContent='Conversa do servidor';els.textView.classList.remove('hidden');els.voiceView.classList.add('hidden');state.socket.emit('messages:load',{serverId:state.selectedServer.id,channelId:c.id});setTimeout(()=>els.messageInput.focus(),0)}else{els.channelIcon.textContent='🔊';els.channelDesc.textContent='Canal de voz';els.textView.classList.add('hidden');els.voiceView.classList.remove('hidden');els.voiceTitle.textContent=c.name;updateVoiceUI()}}
function renderMembers(){els.memberList.innerHTML='';const arr=[...state.members.values()].sort((a,b)=>(b.status==='online')-(a.status==='online')||(ROLE_RANK[b.role||'member']-ROLE_RANK[a.role||'member'])||a.name.localeCompare(b.name));for(const u of arr){const role=u.role||roleFor(u.id);const row=document.createElement('div');row.className='member'+(u.status==='offline'?' offline':'');const av=document.createElement('div');av.className='avatar';avatarStyle(av,u);const tx=document.createElement('div');tx.className='member-name';tx.innerHTML=`<b class="role-color-${role}">${escapeHtml(u.name)}${role==='owner'?' 👑':''}</b><small><span class="status-dot status-${escapeHtml(u.status||'offline')}"></span>${STATUS_LABEL[u.status||'offline']||'Offline'} · <span class="role-badge role-${role}">${ROLE_LABEL[role]}</span></small>`;row.append(av,tx);row.title='Ver perfil';row.addEventListener('click',()=>openMemberProfile(u.id));els.memberList.appendChild(row)}}
function renderMessages(forceBottom=false){if(!state.selectedChannel||state.selectedChannel.type!=='text')return;const wasBottom=els.messages.scrollHeight-els.messages.scrollTop-els.messages.clientHeight<90;els.messages.innerHTML='';for(const m of state.messagesByChannel.get(state.selectedChannel.id)||[]){const u=state.members.get(m.authorId)||{name:'Usuário'};const role=u.role||roleFor(m.authorId);const row=document.createElement('div');row.className='message';const av=document.createElement('div');av.className='avatar';avatarStyle(av,u);const body=document.createElement('div');body.innerHTML=`<div class="msg-head"><b class="role-color-${role}">${escapeHtml(u.name)}</b><small>${fmtTime(m.at)}</small></div><div class="msg-text">${escapeHtml(m.text)}</div>`;row.append(av,body);els.messages.appendChild(row)}if(forceBottom||wasBottom)els.messages.scrollTop=els.messages.scrollHeight}

function updateDmUnreadBadge(){const count=state.dmUnread.size;if(!els.dmUnreadBadge)return;els.dmUnreadBadge.textContent=count>9?'9+':String(count);els.dmUnreadBadge.classList.toggle('hidden',count===0)}
function mergeDmConversation(user,lastMessage){if(!user?.id)return;const i=state.dmConversations.findIndex(c=>c.user?.id===user.id);const next={user,lastMessage:lastMessage||(i>=0?state.dmConversations[i].lastMessage:null)};if(i>=0)state.dmConversations[i]=next;else state.dmConversations.push(next);state.dmConversations.sort((a,b)=>Number(b.lastMessage?.at||0)-Number(a.lastMessage?.at||0))}
function dmPeer(userId){return state.dmConversations.find(c=>c.user?.id===userId)?.user||state.members.get(userId)||null}
function renderDmSidebar(){if(state.viewMode!=='dm')return;els.channels.innerHTML='';const top=document.createElement('div');top.className='dm-sidebar';top.innerHTML='<div class="channel-section-title"><span>Mensagens privadas</span></div><button id="newDmBtn" class="dm-new-btn">＋ Nova mensagem</button><div id="dmConversationList" class="dm-conversation-list"></div>';els.channels.appendChild(top);$('newDmBtn').onclick=openNewDmModal;const list=$('dmConversationList');for(const c of state.dmConversations){const u=c.user;if(!u?.id)continue;const row=document.createElement('button');row.className='dm-row'+(state.activeDmUserId===u.id?' active':'');const av=document.createElement('div');av.className='avatar';avatarStyle(av,u);const txt=document.createElement('div');txt.className='dm-row-text';const preview=c.lastMessage?.text?escapeHtml(c.lastMessage.text):'Iniciar conversa';txt.innerHTML=`<b>${escapeHtml(u.name||'Amigo')}</b><small>${preview}</small>`;const meta=document.createElement('div');meta.className='dm-row-meta';meta.innerHTML=`<span class="status-dot status-${escapeHtml(u.status||'offline')}"></span>${state.dmUnread.has(u.id)?'<span class="dm-unread-dot"></span>':''}`;row.append(av,txt,meta);row.onclick=()=>startDm(u.id,u);list.appendChild(row)}if(!state.dmConversations.length){const empty=document.createElement('div');empty.className='dm-empty-list';empty.textContent='Nenhuma conversa ainda.';list.appendChild(empty)}}
function showDmHome(){state.viewMode='dm';state.activeDmUserId=null;state.selectedChannel=null;els.app.classList.add('dm-mode');els.serverName.textContent='Privado';els.inviteBtn.style.visibility='hidden';els.serverSettingsBtn.style.visibility='hidden';renderServers();renderDmSidebar();els.channelIcon.textContent='💬';els.channelName.textContent='Mensagens privadas';els.channelDesc.textContent='Converse diretamente com seus amigos';els.textView.classList.add('hidden');els.voiceView.classList.add('hidden');els.emptyView.innerHTML='<div class="big-banana">🍌</div><h2>Mensagens privadas</h2><p>Escolha uma conversa na lateral ou inicie uma nova.</p>';els.emptyView.classList.remove('hidden');state.socket?.emit('dm:conversations:get')}
function startDm(userId,user=null){if(!userId||userId===state.user?.id)return;const peer=user||dmPeer(userId);if(peer)mergeDmConversation(peer,null);state.viewMode='dm';state.activeDmUserId=userId;state.selectedChannel=null;state.dmUnread.delete(userId);updateDmUnreadBadge();els.app.classList.add('dm-mode');els.serverName.textContent='Privado';els.inviteBtn.style.visibility='hidden';els.serverSettingsBtn.style.visibility='hidden';renderServers();renderDmSidebar();els.emptyView.classList.add('hidden');els.voiceView.classList.add('hidden');els.textView.classList.remove('hidden');els.channelIcon.textContent='@';els.channelName.textContent=peer?.name||'Mensagem privada';els.channelDesc.textContent='Mensagem privada';els.messageInput.placeholder=`Mensagem para ${peer?.name||'seu amigo'}`;renderDmMessages();state.socket?.emit('dm:load',{userId});setTimeout(()=>els.messageInput.focus(),0)}
function renderDmMessages(forceBottom=false){if(state.viewMode!=='dm'||!state.activeDmUserId)return;const wasBottom=els.messages.scrollHeight-els.messages.scrollTop-els.messages.clientHeight<90;const peer=dmPeer(state.activeDmUserId)||{id:state.activeDmUserId,name:'Amigo'};els.messages.innerHTML='';for(const m of state.dmMessages.get(state.activeDmUserId)||[]){const mine=m.fromId===state.user?.id;const u=mine?state.user:peer;const row=document.createElement('div');row.className='message dm-message';const av=document.createElement('div');av.className='avatar';avatarStyle(av,u);const body=document.createElement('div');body.innerHTML=`<div class="msg-head"><b>${escapeHtml(mine?'Você':u?.name||'Amigo')}</b><small>${fmtTime(m.at)}</small></div><div class="msg-text">${escapeHtml(m.text)}</div>`;row.append(av,body);els.messages.appendChild(row)}if(!els.messages.children.length)els.messages.innerHTML='<div class="dm-conversation-empty"><b>Comece a conversa 👋</b><span>As mensagens ficam armazenadas no Banana Cord do host.</span></div>';if(forceBottom||wasBottom)els.messages.scrollTop=els.messages.scrollHeight}
function openNewDmModal(){const candidates=[...state.members.values()].filter(u=>u.id!==state.user?.id);openModal(`<div class="simple-modal-head"><h2>Nova mensagem</h2><p>Escolha alguém deste servidor.</p></div><div class="dm-picker">${candidates.map(u=>`<button class="dm-picker-row" data-user="${escapeHtml(u.id)}"><span class="dm-picker-avatar avatar" data-avatar="${escapeHtml(u.id)}"></span><span><b>${escapeHtml(u.name)}</b><small>${STATUS_LABEL[u.status||'offline']||'Offline'}</small></span></button>`).join('')||'<p>Nenhum outro membro disponível.</p>'}</div>`);for(const av of document.querySelectorAll('.dm-picker-avatar'))avatarStyle(av,state.members.get(av.dataset.avatar));for(const b of document.querySelectorAll('.dm-picker-row'))b.onclick=()=>{const u=state.members.get(b.dataset.user);closeModal();startDm(b.dataset.user,u)}}

els.messageForm.addEventListener('submit',e=>{e.preventDefault();const text=els.messageInput.value.trim();if(!text)return;if(state.viewMode==='dm'&&state.activeDmUserId){state.socket.emit('dm:send',{userId:state.activeDmUserId,text});els.messageInput.value='';return}if(!state.selectedServer||state.selectedChannel?.type!=='text')return;state.socket.emit('message:send',{serverId:state.selectedServer.id,channelId:state.selectedChannel.id,text});els.messageInput.value=''});
els.homeServer?.addEventListener('click',showDmHome);
els.addServerBtn.addEventListener('click',()=>openModal(`<h2>Servidor</h2><p>Crie um servidor privado ou entre com o código de um servidor deste mesmo host.</p><label>Nome do novo servidor</label><input id="newServerName" maxlength="40" placeholder="Banana Gang"><button id="createServerNow">Criar servidor</button><div class="divider"><span>ou</span></div><label>Código de convite</label><input id="joinCode" maxlength="16" placeholder="A1B2C3D4"><button id="joinServerNow">Entrar pelo código</button>`));
els.modalBody.addEventListener('click',e=>{if(e.target.id==='createServerNow'){const name=$('newServerName')?.value.trim();if(name)state.socket.emit('server:create',{name})}if(e.target.id==='joinServerNow'){const inviteCode=$('joinCode')?.value.trim();if(inviteCode)state.socket.emit('server:join',{inviteCode})}});
function channelModal(type){openModal(`<h2>Novo canal ${type==='voice'?'de voz':'de texto'}</h2><label>Nome</label><input id="newChannelName" maxlength="32" placeholder="${type==='voice'?'Jogando':'jogos'}"><button id="createChannelNow">Criar canal</button>`);$('createChannelNow').addEventListener('click',()=>{const name=$('newChannelName').value.trim();if(name){state.socket.emit('channel:create',{serverId:state.selectedServer.id,type,name});closeModal()}})}
function editChannelModal(c){openModal(`<h2>Editar canal</h2><label>Nome</label><input id="editChannelName" maxlength="32" value="${escapeHtml(c.name)}"><button id="saveChannelName">Salvar nome</button><hr class="settings-sep"><button id="deleteChannel" class="danger-action">Excluir canal</button><p><small>Você pode arrastar canais na lateral para reordená-los.</small></p>`);$('saveChannelName').onclick=()=>{const name=$('editChannelName').value.trim();if(name)state.socket.emit('channel:update',{serverId:state.selectedServer.id,channelId:c.id,name});closeModal()};$('deleteChannel').onclick=()=>{if(confirm(`Excluir #${c.name}?`)){state.socket.emit('channel:update',{serverId:state.selectedServer.id,channelId:c.id,action:'delete'});closeModal()}}}
els.inviteBtn.addEventListener('click',openInviteModal);async function openInviteModal(){if(!state.selectedServer)return;const url=state.isHost?(state.publicHostUrl||state.serverUrl):state.serverUrl;const full=makeInvite(url,state.selectedServer.inviteCode);openModal(`<h2>Convidar para ${escapeHtml(state.selectedServer.name)}</h2><p>Seu amigo instala o Banana Cord e cola este convite na primeira tela:</p><div class="invite-box">${escapeHtml(full)}</div><button id="copyInvite">Copiar convite</button><p><small>Código: <b>${escapeHtml(state.selectedServer.inviteCode)}</b></small></p>${can('admin')?'<button id="regenInvite" class="secondary">Gerar novo código</button>':''}`);$('copyInvite').onclick=copyCurrentInvite;if($('regenInvite'))$('regenInvite').onclick=()=>state.socket.emit('server:regenerate-invite',{serverId:state.selectedServer.id})}
async function copyCurrentInvite(){if(!state.selectedServer)return;const url=state.isHost?(state.publicHostUrl||state.serverUrl):state.serverUrl;await ipcRenderer.invoke('clipboard:write',makeInvite(url,state.selectedServer.inviteCode));toast('Convite copiado.');closeModal()}
els.serverSettingsBtn.addEventListener('click',openServerSettings);
function openServerSettings(){if(!state.selectedServer)return;const s=state.selectedServer;const r=currentRole();const rows=[...state.members.values()].map(u=>{const role=u.role||roleFor(u.id);const canEdit=r==='owner'&&u.id!==s.ownerId;return `<div class="role-row"><div class="avatar role-avatar" data-user="${escapeHtml(u.id)}"></div><div><b>${escapeHtml(u.name)}</b><small>${STATUS_LABEL[u.status||'offline']||'Offline'}</small></div>${canEdit?`<select class="role-select" data-user="${escapeHtml(u.id)}"><option value="member" ${role==='member'?'selected':''}>Membro</option><option value="moderator" ${role==='moderator'?'selected':''}>Moderador</option><option value="admin" ${role==='admin'?'selected':''}>Administrador</option></select><button class="remove-member" data-user="${escapeHtml(u.id)}">Remover</button>`:`<span class="role-badge role-${role}">${ROLE_LABEL[role]}</span><span></span>`}</div>`}).join('');openModal(`<h2>${escapeHtml(s.name)}</h2><div class="server-settings-grid">${can('admin')?`<label>Nome do servidor</label><input id="serverNameEdit" maxlength="40" value="${escapeHtml(s.name)}"><button id="saveServerName">Salvar nome</button>`:''}<div class="permission-note"><b>Cargos</b><br>Dono: tudo. Administrador: servidor, convites e canais. Moderador: criar, editar, apagar e ordenar canais. Membro: conversa e entra nas calls.</div><div class="role-table">${rows||'<p>Carregando membros…</p>'}</div><div class="version-label">Banana Cord v0.10</div></div>`);for(const el of document.querySelectorAll('.role-avatar'))avatarStyle(el,state.members.get(el.dataset.user));$('saveServerName')?.addEventListener('click',()=>{state.socket.emit('server:update',{serverId:s.id,name:$('serverNameEdit').value});closeModal()});for(const sel of document.querySelectorAll('.role-select'))sel.addEventListener('change',()=>state.socket.emit('member:set-role',{serverId:s.id,userId:sel.dataset.user,role:sel.value}));for(const b of document.querySelectorAll('.remove-member'))b.addEventListener('click',()=>{const u=state.members.get(b.dataset.user);if(confirm(`Remover ${u?.name||'membro'} do servidor?`)){state.socket.emit('member:kick',{serverId:s.id,userId:b.dataset.user});closeModal()}})}
function openMemberProfile(userId){const u=state.members.get(userId);if(!u)return;const role=u.role||roleFor(userId);const canDm=userId!==state.user?.id;openModal(`<h2>${escapeHtml(u.name)}</h2><div class="profile-preview"><div id="profilePreviewAvatar" class="avatar" style="width:76px;height:76px;font-size:28px"></div><p><span class="status-dot status-${escapeHtml(u.status||'offline')}"></span>${STATUS_LABEL[u.status||'offline']||'Offline'}</p><span class="role-badge role-${role}">${ROLE_LABEL[role]}</span>${canDm?'<button id="dmFromProfile" class="action">💬 Mensagem privada</button>':''}</div>`);avatarStyle($('profilePreviewAvatar'),u);$('dmFromProfile')?.addEventListener('click',()=>{closeModal();startDm(userId,u)})}
els.profileBtn.addEventListener('click',openSettings);els.updateBadge?.addEventListener('click',async()=>{if(state.updates.state?.status==='downloaded'){await ipcRenderer.invoke('update:install');return}await openSettings();setTimeout(()=>$('tabUpdates')?.click(),0)});

function micConstraints(){const base={echoCancellation:state.media.echoCancellation,noiseSuppression:state.media.noiseSuppression,autoGainControl:state.media.autoGainControl,channelCount:1};if(state.media.micId)base.deviceId={exact:state.media.micId};return base}
function resolutionFor(value){return value==='1080'?{width:1920,height:1080}:value==='480'?{width:854,height:480}:{width:1280,height:720}}
function cameraConstraints(){const q=resolutionFor(state.media.cameraQuality);const c={width:{ideal:q.width},height:{ideal:q.height},frameRate:{ideal:state.media.cameraFps,max:state.media.cameraFps}};if(state.media.cameraId)c.deviceId={exact:state.media.cameraId};return c}
function peerVolume(userId){const v=Number(state.media.peerVolumes?.[userId]);return Number.isFinite(v)?Math.min(1,Math.max(0,v)):1}
async function applyOutputDevice(mediaEl,userId=''){if(!mediaEl)return;const base=Math.min(1,Math.max(0,state.media.outputVolume||0));mediaEl.volume=state.voice.deafened?0:Math.min(1,base*peerVolume(userId));if(state.media.speakerId&&typeof mediaEl.setSinkId==='function'){try{await mediaEl.setSinkId(state.media.speakerId)}catch(e){console.warn('speaker output',e)}}}
async function enumerateMediaDevices(withPermission=false){let temp=null;if(withPermission){try{temp=await navigator.mediaDevices.getUserMedia({audio:true,video:false})}catch{}}const devices=await navigator.mediaDevices.enumerateDevices();temp?.getTracks().forEach(t=>t.stop());return devices}
function fillDeviceSelect(select,devices,kind,current,label){if(!select)return;const rows=devices.filter(d=>d.kind===kind);select.innerHTML='';const def=document.createElement('option');def.value='';def.textContent=`Padrão do Windows (${label})`;select.appendChild(def);rows.forEach((d,i)=>{const o=document.createElement('option');o.value=d.deviceId;o.textContent=d.label||`${label} ${i+1}`;select.appendChild(o)});select.value=rows.some(d=>d.deviceId===current)?current:''}

let micTest={stream:null,ctx:null,raf:null,recorder:null,chunks:[],url:'',audio:null,timer:null,discarding:false};
function cleanupMicLive(test){if(!test)return;if(test.raf)cancelAnimationFrame(test.raf);clearTimeout(test.timer);test.stream?.getTracks().forEach(t=>t.stop());try{test.ctx?.close()}catch{}test.stream=null;test.ctx=null;test.raf=null;test.timer=null}
function stopMicPlayback(){const a=micTest.audio;if(a){try{a.pause();a.currentTime=0}catch{}micTest.audio=null}if($('playMicBtn'))$('playMicBtn').textContent='▶ Ouvir gravação'}
function stopMicTest(){const test=micTest;test.discarding=true;stopMicPlayback();if(test.recorder?.state==='recording'){try{test.recorder.stop()}catch{}}cleanupMicLive(test);if(test.url){try{URL.revokeObjectURL(test.url)}catch{}}micTest={stream:null,ctx:null,raf:null,recorder:null,chunks:[],url:'',audio:null,timer:null,discarding:false};if($('micLevelBar'))$('micLevelBar').style.width='0%';if($('micTestState'))$('micTestState').textContent='Grave uma frase e depois ouça exatamente como seu microfone está saindo.';if($('testMicBtn'))$('testMicBtn').textContent='● Gravar teste';if($('playMicBtn'))$('playMicBtn').classList.add('hidden')}
function finishMicRecording(){const test=micTest;if(test.recorder?.state==='recording'){clearTimeout(test.timer);test.timer=null;try{test.recorder.stop()}catch{}}}
async function startMicTest(){stopMicTest();try{const c={echoCancellation:$('echoCancellation')?.checked??state.media.echoCancellation,noiseSuppression:$('noiseSuppression')?.checked??state.media.noiseSuppression,autoGainControl:$('autoGainControl')?.checked??state.media.autoGainControl,channelCount:1};const selected=$('micSelect')?.value||state.media.micId;if(selected)c.deviceId={exact:selected};const stream=await navigator.mediaDevices.getUserMedia({audio:c,video:false});const ctx=new AudioContext(),source=ctx.createMediaStreamSource(stream),analyser=ctx.createAnalyser();analyser.fftSize=512;source.connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount);const opts=typeof MediaRecorder!=='undefined'&&MediaRecorder.isTypeSupported?.('audio/webm;codecs=opus')?{mimeType:'audio/webm;codecs=opus'}:{};const recorder=new MediaRecorder(stream,opts);const test={stream,ctx,raf:null,recorder,chunks:[],url:'',audio:null,timer:null,discarding:false};micTest=test;recorder.ondataavailable=e=>{if(e.data?.size)test.chunks.push(e.data)};recorder.onstop=()=>{cleanupMicLive(test);if(test.discarding)return;const blob=new Blob(test.chunks,{type:recorder.mimeType||'audio/webm'});if(!blob.size){if($('micTestState'))$('micTestState').textContent='Não consegui gerar a gravação. Tente novamente.';return}test.url=URL.createObjectURL(blob);test.recorder=null;if($('micLevelBar'))$('micLevelBar').style.width='0%';if($('micTestState'))$('micTestState').textContent='Gravação pronta. Clique em “Ouvir gravação”.';if($('testMicBtn'))$('testMicBtn').textContent='● Gravar novamente';if($('playMicBtn'))$('playMicBtn').classList.remove('hidden')};recorder.start(150);$('micTestState').textContent='Gravando… fale normalmente. O teste para sozinho em até 8 segundos.';$('testMicBtn').textContent='■ Parar gravação';const tick=()=>{analyser.getByteTimeDomainData(data);let sum=0;for(const v of data){const n=(v-128)/128;sum+=n*n}const level=Math.min(100,Math.round(Math.sqrt(sum/data.length)*360));if($('micLevelBar'))$('micLevelBar').style.width=`${level}%`;test.raf=requestAnimationFrame(tick)};tick();test.timer=setTimeout(finishMicRecording,8000)}catch{toast('Não consegui acessar esse microfone. Confira a permissão do Windows.',4000)}}
async function playMicRecording(){if(!micTest.url)return;if(micTest.audio&&!micTest.audio.paused){stopMicPlayback();if($('micTestState'))$('micTestState').textContent='Reprodução parada.';return}try{const audio=new Audio(micTest.url);audio.volume=Math.min(1,Math.max(0,Number($('outputVolume')?.value??state.media.outputVolume)));const sink=$('speakerSelect')?.value||state.media.speakerId;if(sink&&typeof audio.setSinkId==='function')await audio.setSinkId(sink);micTest.audio=audio;$('playMicBtn').textContent='■ Parar reprodução';$('micTestState').textContent='Reproduzindo sua gravação…';audio.onended=()=>{if(micTest.audio===audio)micTest.audio=null;if($('playMicBtn'))$('playMicBtn').textContent='▶ Ouvir gravação';if($('micTestState'))$('micTestState').textContent='Gravação pronta. Você pode ouvir novamente ou gravar outra.'};await audio.play()}catch{toast('Não consegui reproduzir a gravação nessa saída.',3500)}}
async function testSpeaker(){try{const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain(),dest=ctx.createMediaStreamDestination();osc.frequency.value=523.25;gain.gain.value=.12;osc.connect(gain).connect(dest);osc.start();const audio=new Audio();audio.srcObject=dest.stream;audio.volume=Math.min(1,Math.max(0,Number($('outputVolume')?.value??state.media.outputVolume)));const sink=$('speakerSelect')?.value||state.media.speakerId;if(sink&&typeof audio.setSinkId==='function')await audio.setSinkId(sink);await audio.play();setTimeout(()=>{try{osc.stop();audio.pause();ctx.close()}catch{}},700)}catch{toast('Não consegui tocar o som de teste nessa saída.',3500)}}
let cameraTest={stream:null};function stopCameraTest(){cameraTest.stream?.getTracks().forEach(t=>t.stop());cameraTest={stream:null};if($('cameraPreview'))$('cameraPreview').srcObject=null;if($('testCameraBtn'))$('testCameraBtn').textContent='📹 Testar câmera'}
async function startCameraTest(){stopCameraTest();try{const q=resolutionFor($('cameraQuality')?.value||state.media.cameraQuality),fps=Number($('cameraFps')?.value||state.media.cameraFps),c={width:{ideal:q.width},height:{ideal:q.height},frameRate:{ideal:fps,max:fps}};const id=$('cameraSelect')?.value||state.media.cameraId;if(id)c.deviceId={exact:id};cameraTest.stream=await navigator.mediaDevices.getUserMedia({video:c,audio:false});const v=$('cameraPreview');v.srcObject=cameraTest.stream;v.play().catch(()=>{});$('testCameraBtn').textContent='⏹ Parar câmera'}catch{toast('Não consegui abrir essa câmera.',3500)}}
async function refreshAllOutputs(){for(const p of state.voice.peers.values())await applyOutputDevice($(`video-${p.socketId}`)?.querySelector('audio.remote-audio'),p.user?.id||'')}
async function switchMicrophoneInCall(){if(!state.voice.channelId)return;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:micConstraints(),video:false})}catch{return toast('Não consegui trocar o microfone durante a chamada.',4000)}const track=stream.getAudioTracks()[0];const old=state.voice.localAudio;state.voice.localAudio=stream;applyMicTrackState();for(const p of state.voice.peers.values()){let sender=p.pc.getSenders().find(s=>s._bananaMic);if(sender)await sender.replaceTrack(track);else{sender=p.pc.addTrack(track,stream);sender._bananaMic=true;await renegotiate(p)}}old?.getTracks().forEach(t=>t.stop());startLocalVAD();toast('Microfone atualizado na chamada.')}

function diagnosticsHtml(){const peers=[...state.voice.peers.values()];const rows=peers.length?peers.map(p=>`<div class="diag-row"><b>${escapeHtml(p.user?.name||'Amigo')}</b><span>WebRTC: ${escapeHtml(p.pc.connectionState||'novo')} · ICE: ${escapeHtml(p.pc.iceConnectionState||'novo')} · áudio ${p.remoteStream.getAudioTracks().filter(t=>t.readyState==='live').length} · vídeo ${p.remoteStream.getVideoTracks().filter(t=>t.readyState==='live').length}</span></div>`).join(''):'<p><small>Você não está conectado a outras pessoas em uma sala de voz.</small></p>';return`<div class="diagnostics"><div class="diag-row"><b>Servidor</b><span>${escapeHtml(state.serverUrl||'--')}</span></div><div class="diag-row"><b>Ping do servidor</b><span>${escapeHtml(els.ping.textContent||'--')}</span></div><div class="diag-row"><b>Sala de voz</b><span>${state.voice.channelId?'Conectado':'Fora da voz'}</span></div>${rows}<div class="settings-actions"><button class="secondary" id="refreshDiag">Atualizar diagnóstico</button><button class="secondary" id="reconnectVoice">Reconectar voz</button></div></div>`}
async function openSettings(){
  stopMicTest();stopCameraTest();
  const nav=[['tabProfile','👤','Perfil','Nome, foto e presença'],['tabAudio','🎙','Áudio','Microfone e saída'],['tabVideo','🖥','Vídeo e tela','Câmera e compartilhamento'],['tabGeneral','⌨','Geral','Atalhos e comportamento'],['tabDiag','◉','Diagnóstico','Conexão e WebRTC'],['tabUpdates','↻','Atualizações','Versões do Banana Cord']];
  openModal(`<div class="settings-shell"><aside class="settings-nav"><div class="settings-brand"><div class="settings-banana">🍌</div><div><b>Banana Cord</b><small>Configurações</small></div></div><div class="settings-nav-list">${nav.map(([id,icon,label])=>`<button id="${id}" class="settings-nav-item"><span>${icon}</span><b>${label}</b></button>`).join('')}</div><div class="settings-nav-foot">v${escapeHtml(state.updates.config?.currentVersion||'0.10.0')}</div></aside><section class="settings-content"><div class="settings-content-head"><span>CONFIGURAÇÕES</span><h2 id="settingsTitle">Perfil</h2><p id="settingsSubtitle">Nome, foto e presença</p></div><div id="settingsArea"></div></section></div>`);
  els.modal.querySelector('.modal-card')?.classList.add('settings-modal');
  const area=$('settingsArea');
  const meta=Object.fromEntries(nav.map(([id,_icon,label,sub])=>[id,[label,sub]]));
  const activate=id=>{for(const [x] of nav)$(x)?.classList.toggle('active',x===id);const [title,sub]=meta[id]||['Configurações',''];if($('settingsTitle'))$('settingsTitle').textContent=title;if($('settingsSubtitle'))$('settingsSubtitle').textContent=sub};
  const showProfile=()=>{stopMicTest();stopCameraTest();activate('tabProfile');area.innerHTML=`<div class="settings-card"><div class="settings-card-head"><div><span class="settings-kicker">IDENTIDADE</span><h3>Seu perfil</h3><p>Como seus amigos veem você dentro do Banana Cord.</p></div><div id="settingsAvatarPreview" class="avatar settings-avatar"></div></div><div class="settings-form-grid"><div class="settings-field"><label>Nome</label><input id="profileName" maxlength="32" value="${escapeHtml(state.user?.name||'')}"></div><div class="settings-field"><label>Status</label><select id="profileStatus" class="profile-status-select"><option value="online">Online</option><option value="busy">Ocupado</option><option value="away">Ausente</option></select></div></div><div class="settings-field"><label>Foto de perfil</label><input id="profileFile" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG ou WebP de até 900 KB.</small></div><div class="settings-actions"><button class="action" id="saveProfile">Salvar perfil</button></div></div><div class="settings-card settings-card-muted"><div class="settings-card-head compact"><div><span class="settings-kicker">CONEXÃO</span><h3>Sessão atual</h3><p class="settings-url">${escapeHtml(state.serverUrl||'Nenhum servidor conectado')}</p></div></div><button class="secondary" id="disconnectNow">Desconectar</button></div>`;$('profileStatus').value=state.user?.status==='offline'?'online':state.user?.status||state.ui.status;let avatarData=state.user?.avatar||'';avatarStyle($('settingsAvatarPreview'),state.user||{name:'Você',avatar:avatarData});$('profileFile').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>900000)return toast('Escolha uma imagem menor que 900 KB.');const r=new FileReader();r.onload=()=>{avatarData=r.result;avatarStyle($('settingsAvatarPreview'),{name:$('profileName').value||state.user?.name||'Você',avatar:avatarData})};r.readAsDataURL(file)};$('saveProfile').onclick=()=>{state.ui.status=$('profileStatus').value;savePrefs();state.socket.emit('profile:update',{name:$('profileName').value,avatar:avatarData,status:state.ui.status});closeModal()};$('disconnectNow').onclick=()=>location.reload()};
  const showAudio=async()=>{stopCameraTest();stopMicTest();activate('tabAudio');area.innerHTML=`<div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">ENTRADA</span><h3>Microfone</h3><p>Escolha o dispositivo e faça um teste ouvindo sua própria gravação.</p></div></div><div class="settings-field"><label>Dispositivo de entrada</label><select id="micSelect"><option>Carregando…</option></select></div><div class="mic-test-box"><div class="mic-test-copy"><b>Teste do microfone</b><small id="micTestState">Grave uma frase e depois ouça exatamente como seu microfone está saindo.</small></div><div class="mic-meter"><span id="micLevelBar"></span></div><div class="mic-test-actions"><button class="secondary" id="testMicBtn">● Gravar teste</button><button class="secondary hidden" id="playMicBtn">▶ Ouvir gravação</button></div></div><div class="settings-field"><label>Sensibilidade da voz <span id="thresholdLabel">${state.media.voiceThreshold}</span></label><input id="voiceThreshold" type="range" min="3" max="45" step="1" value="${state.media.voiceThreshold}"><small>Controla quando o contorno verde indica que você está falando.</small></div></div><div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">PROCESSAMENTO</span><h3>Tratamento de voz</h3><p>Recursos leves do Chromium para deixar a conversa mais limpa.</p></div></div><div class="switch-grid"><label class="switch-line"><input id="echoCancellation" type="checkbox" ${state.media.echoCancellation?'checked':''}> Cancelamento de eco</label><label class="switch-line"><input id="noiseSuppression" type="checkbox" ${state.media.noiseSuppression?'checked':''}> Redução de ruído</label><label class="switch-line"><input id="autoGainControl" type="checkbox" ${state.media.autoGainControl?'checked':''}> Ganho automático</label><label class="switch-line"><input id="autoMute" type="checkbox" ${state.media.autoMute?'checked':''}> Entrar mutado</label></div></div><div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">SAÍDA</span><h3>Fone / alto-falante</h3><p>Escolha onde ouvir as pessoas e os testes.</p></div></div><div class="settings-field"><label>Dispositivo de saída</label><select id="speakerSelect"><option>Carregando…</option></select></div><div class="settings-field"><label>Volume geral <span id="volumeLabel">${Math.round(state.media.outputVolume*100)}%</span></label><input id="outputVolume" type="range" min="0" max="1" step="0.01" value="${state.media.outputVolume}"></div><div class="settings-actions"><button class="secondary" id="testSpeakerBtn">🔊 Testar saída</button><button class="secondary" id="refreshDevicesBtn">↻ Atualizar dispositivos</button><button class="action" id="saveAudioSettings">Salvar áudio</button></div></div>`;const load=async()=>{try{const d=await enumerateMediaDevices(true);fillDeviceSelect($('micSelect'),d,'audioinput',state.media.micId,'Microfone');fillDeviceSelect($('speakerSelect'),d,'audiooutput',state.media.speakerId,'Saída')}catch{toast('Não consegui listar os dispositivos.')}};await load();$('testMicBtn').onclick=()=>micTest.recorder?.state==='recording'?finishMicRecording():startMicTest();$('playMicBtn').onclick=playMicRecording;$('testSpeakerBtn').onclick=testSpeaker;$('refreshDevicesBtn').onclick=load;$('voiceThreshold').oninput=e=>$('thresholdLabel').textContent=e.target.value;$('outputVolume').oninput=async e=>{state.media.outputVolume=Number(e.target.value);$('volumeLabel').textContent=`${Math.round(state.media.outputVolume*100)}%`;if(micTest.audio)micTest.audio.volume=state.media.outputVolume;await refreshAllOutputs()};$('saveAudioSettings').onclick=async()=>{const oldMic=state.media.micId;state.media.micId=$('micSelect').value;state.media.speakerId=$('speakerSelect').value;state.media.outputVolume=Number($('outputVolume').value);state.media.voiceThreshold=Number($('voiceThreshold').value);state.media.echoCancellation=$('echoCancellation').checked;state.media.noiseSuppression=$('noiseSuppression').checked;state.media.autoGainControl=$('autoGainControl').checked;state.media.autoMute=$('autoMute').checked;savePrefs();stopMicTest();await refreshAllOutputs();if(state.voice.channelId&&oldMic!==state.media.micId)await switchMicrophoneInCall();toast('Configurações de áudio salvas.');showAudio()}};
  const showVideo=async()=>{stopMicTest();activate('tabVideo');area.innerHTML=`<div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">CÂMERA</span><h3>Vídeo</h3><p>Use qualidade alta quando quiser; durante jogos, 720p/30 costuma consumir menos.</p></div></div><div class="settings-field"><label>Câmera</label><select id="cameraSelect"><option>Carregando…</option></select></div><div class="settings-2col"><div class="settings-field"><label>Qualidade</label><select id="cameraQuality"><option value="480">480p</option><option value="720">720p</option><option value="1080">1080p</option></select></div><div class="settings-field"><label>FPS</label><select id="cameraFps"><option value="30">30 FPS</option><option value="60">60 FPS</option></select></div></div><button class="secondary" id="testCameraBtn">📹 Testar câmera</button><video id="cameraPreview" class="camera-preview" autoplay muted playsinline></video></div><div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">COMPARTILHAMENTO</span><h3>Tela</h3><p>O modo automático tenta equilibrar nitidez e estabilidade sem pesar no jogo.</p></div></div><div class="settings-field"><label>Perfil</label><select id="streamPreset"><option value="auto">Automático (recomendado)</option><option value="quality">Qualidade</option><option value="smooth">Fluidez</option><option value="economy">Economia de banda</option></select></div><div class="settings-2col"><div class="settings-field"><label>Qualidade da tela</label><select id="screenQuality"><option value="720">720p</option><option value="1080">1080p</option></select></div><div class="settings-field"><label>FPS da tela</label><select id="screenFps"><option value="30">30 FPS</option><option value="60">60 FPS</option></select></div></div><div class="switch-grid"><label class="switch-line"><input id="autoFocusShare" type="checkbox" ${state.ui.autoFocusShare?'checked':''}> Focar tela compartilhada</label><label class="switch-line"><input id="showStats" type="checkbox" ${state.ui.showStats?'checked':''}> Mostrar ping/bitrate</label></div><div class="settings-help">Quando você compartilha a tela, o Banana Cord prioriza o stream e deixa de enviar sua webcam junto, reduzindo CPU e upload.</div><div class="settings-actions"><button class="action" id="saveVideoSettings">Salvar vídeo e tela</button></div></div>`;try{const d=await enumerateMediaDevices(false);fillDeviceSelect($('cameraSelect'),d,'videoinput',state.media.cameraId,'Câmera')}catch{}$('cameraQuality').value=state.media.cameraQuality;$('cameraFps').value=String(state.media.cameraFps);$('screenQuality').value=state.media.screenQuality;$('screenFps').value=String(state.media.screenFps);$('streamPreset').value=state.media.streamPreset;$('testCameraBtn').onclick=()=>cameraTest.stream?stopCameraTest():startCameraTest();$('saveVideoSettings').onclick=()=>{state.media.cameraId=$('cameraSelect').value;state.media.cameraQuality=$('cameraQuality').value;state.media.cameraFps=Number($('cameraFps').value);state.media.screenQuality=$('screenQuality').value;state.media.screenFps=Number($('screenFps').value);state.media.streamPreset=$('streamPreset').value;state.ui.autoFocusShare=$('autoFocusShare').checked;state.ui.showStats=$('showStats').checked;savePrefs();stopCameraTest();refreshStatsVisibility();toast('Configurações de vídeo salvas.')}};
  const showGeneral=()=>{stopMicTest();stopCameraTest();activate('tabGeneral');area.innerHTML=`<div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">CHAMADAS</span><h3>Comportamento</h3><p>Preferências simples para entrar e sair de calls.</p></div></div><div class="switch-grid"><label class="switch-line"><input id="joinLeaveSounds" type="checkbox" ${state.ui.joinLeaveSounds?'checked':''}> Sons de entrada/saída</label><label class="switch-line"><input id="pttEnabled" type="checkbox" ${state.ui.pttEnabled?'checked':''}> Push-to-talk</label></div><div class="settings-field"><label>Tecla do push-to-talk</label><button class="secondary key-capture" id="capturePttKey">${escapeHtml(prettyKey(state.ui.pttKey))}</button></div><div class="settings-help"><b>Atalhos globais durante o jogo</b><br>Ctrl+Shift+M → mute · Ctrl+Shift+D → ensurdecer · Ctrl+Shift+S → compartilhar tela.</div><div class="settings-actions"><button class="action" id="saveGeneral">Salvar geral</button></div></div>`;$('capturePttKey').onclick=()=>{const btn=$('capturePttKey');btn.textContent='Pressione uma tecla…';const handler=e=>{e.preventDefault();state.ui.pttKey=e.code;btn.textContent=prettyKey(e.code);window.removeEventListener('keydown',handler,true)};window.addEventListener('keydown',handler,true)};$('saveGeneral').onclick=()=>{state.ui.joinLeaveSounds=$('joinLeaveSounds').checked;state.ui.pttEnabled=$('pttEnabled').checked;savePrefs();applyMicTrackState();toast('Configurações gerais salvas.')}};
  const showDiag=()=>{stopMicTest();stopCameraTest();activate('tabDiag');area.innerHTML=`<div class="settings-card"><div class="settings-card-head compact"><div><span class="settings-kicker">REDE</span><h3>Diagnóstico da chamada</h3><p>Use esta tela para separar problema de dispositivo de problema de conexão.</p></div></div>${diagnosticsHtml()}</div>`;$('refreshDiag').onclick=showDiag;$('reconnectVoice').onclick=async()=>{await reconnectCurrentVoice();showDiag()}};
  const showUpdates=async()=>{stopMicTest();stopCameraTest();activate('tabUpdates');let cfg=state.updates.config||{},ust=state.updates.state||{};try{cfg=await ipcRenderer.invoke('update:get-config');ust=await ipcRenderer.invoke('update:get-state');state.updates.config=cfg;state.updates.state=ust}catch{}const labels={idle:'Pronto para verificar',checking:'Verificando…',available:'Nova versão disponível',downloading:'Baixando atualização…',downloaded:'Atualização pronta','up-to-date':'Você está atualizado','not-configured':'Fonte não configurada',dev:'Disponível no app instalado',error:'Erro na atualização'};const statusLabel=labels[ust.status]||ust.message||'--';area.innerHTML=`<div class="settings-card update-settings"><div class="settings-card-head compact"><div><span class="settings-kicker">BANANA CORD</span><h3>Atualizações</h3><p>As novas versões vêm do seu repositório oficial no GitHub.</p></div></div><div class="update-version"><div><small>VERSÃO INSTALADA</small><b>${escapeHtml(cfg.currentVersion||ust.currentVersion||'0.10.0')}</b></div><div><small>ÚLTIMA VERSÃO</small><b>${escapeHtml(ust.latestVersion||'--')}</b></div></div><div class="settings-field"><label>Repositório público</label><input id="updateRepoUrl" value="${escapeHtml(cfg.repoUrl||'')}" placeholder="https://github.com/rafaelmingroni/banana-cord"></div><div class="switch-grid"><label class="switch-line"><input id="autoCheckUpdates" type="checkbox" ${cfg.autoCheck!==false?'checked':''}> Verificar ao abrir</label><label class="switch-line"><input id="autoDownloadUpdates" type="checkbox" ${cfg.autoDownload!==false?'checked':''}> Baixar automaticamente</label></div><div class="update-status"><b>${escapeHtml(statusLabel)}</b><small>${escapeHtml(ust.message||'')}</small><div class="update-progress"><span style="width:${Math.max(0,Math.min(100,Number(ust.progress||0)))}%"></span></div></div><div class="settings-actions"><button class="action" id="saveUpdateSettings">Salvar</button><button class="secondary" id="checkUpdateNow">Verificar agora</button>${ust.status==='available'?'<button class="secondary" id="downloadUpdateNow">Baixar</button>':''}${ust.status==='downloaded'?'<button class="action" id="installUpdateNow">Reiniciar e instalar</button>':''}</div></div>`;$('saveUpdateSettings').onclick=async()=>{try{state.updates.config=await ipcRenderer.invoke('update:save-config',{repoUrl:$('updateRepoUrl').value.trim(),autoCheck:$('autoCheckUpdates').checked,autoDownload:$('autoDownloadUpdates').checked});toast('Configurações de atualização salvas.');showUpdates()}catch(e){toast(e?.message||'Não consegui salvar.',4500)}};$('checkUpdateNow').onclick=async()=>{try{await ipcRenderer.invoke('update:check')}catch(e){toast(e?.message||'Falha ao verificar.',4500)}showUpdates()};if($('downloadUpdateNow'))$('downloadUpdateNow').onclick=async()=>{try{await ipcRenderer.invoke('update:download')}catch(e){toast(e?.message||'Falha ao baixar.',4500)}};if($('installUpdateNow'))$('installUpdateNow').onclick=()=>ipcRenderer.invoke('update:install')};
  $('tabProfile').onclick=showProfile;$('tabAudio').onclick=showAudio;$('tabVideo').onclick=showVideo;$('tabGeneral').onclick=showGeneral;$('tabDiag').onclick=showDiag;$('tabUpdates').onclick=showUpdates;showProfile();
}
function prettyKey(code){return String(code||'KeyV').replace(/^Key/,'').replace(/^Digit/,'').replace('Control','Ctrl ').replace('Shift','Shift ').replace('Alt','Alt ')}

els.joinVoiceBtn.addEventListener('click',async()=>{if(state.voice.channelId===state.selectedChannel?.id)return leaveVoice();await joinVoice(state.selectedChannel)});els.hangupBtn.addEventListener('click',leaveVoice);els.muteBtn.addEventListener('click',toggleMute);els.deafenBtn.addEventListener('click',toggleDeafen);els.cameraBtn.addEventListener('click',toggleCamera);els.screenBtn.addEventListener('click',toggleScreen);els.reconnectVoiceBtn.addEventListener('click',reconnectCurrentVoice);els.hideCamsBtn.addEventListener('click',()=>{state.ui.showAllOverride=!state.ui.showAllOverride;applyFocusSharing()});
function toggleMute(){if(!state.voice.channelId)return;state.voice.muted=!state.voice.muted;applyMicTrackState();els.muteBtn.classList.toggle('off',state.voice.muted);els.muteBtn.textContent=state.voice.muted?'🔇':'🎤';updateLocalVideo();emitMediaState();if(state.voice.muted)setLocalSpeaking(false)}
async function toggleDeafen(){if(!state.voice.channelId)return;state.voice.deafened=!state.voice.deafened;els.deafenBtn.classList.toggle('off',state.voice.deafened);els.deafenBtn.textContent=state.voice.deafened?'🔕':'🎧';await refreshAllOutputs()}
function applyMicTrackState(){const enabled=!state.voice.muted&&(!state.ui.pttEnabled||state.voice.pttHeld);for(const t of state.voice.localAudio?.getAudioTracks()||[])t.enabled=enabled;if(!enabled)setLocalSpeaking(false)}
function emitMediaState(){if(state.voice.channelId&&state.socket?.connected)state.socket.emit('voice:media-state',{muted:state.voice.muted|| (state.ui.pttEnabled&&!state.voice.pttHeld),camera:!!state.voice.camera,screen:!!state.voice.screen})}
function setCardSpeaking(id,on){$(id)?.classList.toggle('speaking',!!on)}
function setLocalSpeaking(on){if(state.voice.speaking===!!on)return;state.voice.speaking=!!on;setCardSpeaking('video-local',state.voice.speaking);if(state.voice.channelId)state.socket.emit('voice:speaking',{speaking:state.voice.speaking})}
function stopLocalVAD(){const v=state.voice.vad;if(!v)return;if(v.raf)cancelAnimationFrame(v.raf);try{v.ctx?.close()}catch{}state.voice.vad=null;state.voice.speaking=false;setCardSpeaking('video-local',false)}
function startLocalVAD(){stopLocalVAD();if(!state.voice.localAudio?.getAudioTracks().length)return;try{const ctx=new AudioContext(),src=ctx.createMediaStreamSource(state.voice.localAudio),analyser=ctx.createAnalyser();analyser.fftSize=512;analyser.smoothingTimeConstant=.45;src.connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount),vad={ctx,analyser,data,raf:null,quietSince:0};state.voice.vad=vad;const tick=()=>{if(state.voice.vad!==vad)return;analyser.getByteTimeDomainData(data);let sum=0;for(const v of data){const n=(v-128)/128;sum+=n*n}const level=Math.min(100,Math.round(Math.sqrt(sum/data.length)*360)),threshold=state.media.voiceThreshold,now=performance.now(),allowed=!state.voice.muted&&(!state.ui.pttEnabled||state.voice.pttHeld);if(allowed&&level>=threshold){vad.quietSince=0;setLocalSpeaking(true)}else if(state.voice.speaking){if(!vad.quietSince)vad.quietSince=now;if(now-vad.quietSince>220)setLocalSpeaking(false)}vad.raf=requestAnimationFrame(tick)};tick()}catch(e){console.warn('VAD',e)}}

async function joinVoice(channel){if(!channel||channel.type!=='voice')return;if(state.voice.channelId)await leaveVoice();try{state.voice.localAudio=await navigator.mediaDevices.getUserMedia({audio:micConstraints(),video:false})}catch{return toast('Não consegui acessar seu microfone. Abra ⚙️ → Áudio e teste o microfone.')}state.voice.serverId=state.selectedServer.id;state.voice.channelId=channel.id;state.voice.muted=!!state.media.autoMute;state.voice.deafened=false;state.voice.pttHeld=false;applyMicTrackState();state.socket.emit('voice:join',{serverId:state.voice.serverId,channelId:channel.id});addLocalCard();startLocalVAD();updateVoiceUI();startPeerStats();setTimeout(emitMediaState,250)}
async function leaveVoice(){if(state.voice.channelId&&state.socket?.connected)state.socket.emit('voice:leave');cleanupVoice();updateVoiceUI()}
function clearPeersOnly(){for(const p of state.voice.peers.values()){try{p.pc.close()}catch{}$(`video-${p.socketId}`)?.remove()}state.voice.peers.clear()}
async function rejoinVoiceTransport(){if(!state.voice.channelId||!state.socket?.connected)return;clearPeersOnly();state.socket.emit('voice:join',{serverId:state.voice.serverId,channelId:state.voice.channelId});addLocalCard();startPeerStats();setTimeout(emitMediaState,250)}
async function reconnectCurrentVoice(){if(!state.voice.channelId)return toast('Entre em uma sala de voz primeiro.');await rejoinVoiceTransport();toast('Reconectando voz…')}
function cleanupVoice(){clearInterval(state.voice.statsTimer);clearTimeout(state.voice.rejoinTimer);stopLocalVAD();clearPeersOnly();for(const stream of[state.voice.localAudio,state.voice.camera,state.voice.screen])stream?.getTracks().forEach(t=>t.stop());state.voice={channelId:null,serverId:null,localAudio:null,camera:null,screen:null,muted:false,deafened:false,speaking:false,pttHeld:false,peers:new Map(),statsTimer:null,vad:null,rejoinTimer:null};els.videoGrid.innerHTML='';els.videoGrid.classList.remove('focus-sharing','has-pin');els.voiceControls.classList.add('hidden');els.muteBtn.classList.remove('off');els.muteBtn.textContent='🎤';els.deafenBtn.classList.remove('off');els.deafenBtn.textContent='🎧';els.cameraBtn.classList.remove('off');els.screenBtn.classList.remove('off');state.ui.focusSharing=false;state.ui.showAllOverride=false}
function updateVoiceUI(){const connected=!!state.voice.channelId;els.voiceControls.classList.toggle('hidden',!connected);els.reconnectVoiceBtn.classList.toggle('hidden',!connected);els.hideCamsBtn.classList.toggle('hidden',!connected);if(connected){const s=state.servers.find(x=>x.id===state.voice.serverId),c=s?.channels.find(x=>x.id===state.voice.channelId);els.voiceChannelName.textContent=c?.name||'Voz'}const here=connected&&state.selectedChannel?.id===state.voice.channelId;els.joinVoiceBtn.textContent=here?'Sair da voz':'Entrar na voz';els.voiceSubtitle.textContent=here?`${state.voice.peers.size+1} conectado(s) · máximo 5`:'Conecte-se para conversar.';els.muteBtn.classList.toggle('off',state.voice.muted);els.muteBtn.textContent=state.voice.muted?'🔇':'🎤';applyFocusSharing()}
function applyFocusSharing(){const anyShare=!![...state.voice.peers.values()].find(p=>p.mediaState?.screen)||!!state.voice.screen;const focus=!state.ui.showAllOverride&&(state.ui.focusSharing||(state.ui.autoFocusShare&&anyShare));els.videoGrid.classList.toggle('focus-sharing',focus);els.hideCamsBtn.classList.toggle('active',focus);els.hideCamsBtn.textContent=focus?'👁 Mostrar todos':'👁 Focar tela'}

function expandCard(card){if(!card)return;if(document.fullscreenElement)document.exitFullscreen?.();else card.requestFullscreen?.().catch(()=>toast('Não consegui abrir em tela cheia.'))}
function wireExpand(card){if(card.dataset.expandReady)return;card.dataset.expandReady='1';card.querySelector('.expand-btn')?.addEventListener('click',e=>{e.stopPropagation();expandCard(card)});card.querySelector('.pin-btn')?.addEventListener('click',e=>{e.stopPropagation();const was=card.classList.contains('pinned');for(const c of els.videoGrid.querySelectorAll('.video-card'))c.classList.remove('pinned');card.classList.toggle('pinned',!was);els.videoGrid.classList.toggle('has-pin',!was)});card.addEventListener('dblclick',()=>{if(card.querySelector('video')?.style.display!=='none')expandCard(card)})}
function addLocalCard(){let card=$('video-local');if(!card){card=document.createElement('div');card.className='video-card';card.id='video-local';card.innerHTML='<div class="video-placeholder"><div class="avatar-video">🍌</div></div><video autoplay muted playsinline></video><button class="expand-btn hidden" title="Tela cheia">⛶</button><button class="pin-btn" title="Fixar">📌</button><div class="video-label">Você</div><div class="peer-stats">local</div>';els.videoGrid.prepend(card);wireExpand(card)}updateLocalVideo();setCardSpeaking('video-local',state.voice.speaking);refreshStatsVisibility()}
function updateLocalVideo(){const card=$('video-local');if(!card)return;const video=card.querySelector('video'),ph=card.querySelector('.video-placeholder'),exp=card.querySelector('.expand-btn'),stream=state.voice.screen||state.voice.camera;video.srcObject=stream||null;video.style.display=stream?'block':'none';ph.style.display=stream?'none':'grid';exp?.classList.toggle('hidden',!stream);card.classList.toggle('is-sharing',!!state.voice.screen);card.querySelector('.video-label').textContent=state.voice.screen?'Você · compartilhando tela':state.voice.muted?'Você · 🔇':'Você';applyFocusSharing()}
async function toggleCamera(){if(!state.voice.channelId)return;if(state.voice.camera){state.voice.camera.getTracks().forEach(t=>t.stop());state.voice.camera=null;if(!state.voice.screen)await setOutgoingVideo(null);updateLocalVideo();els.cameraBtn.classList.add('off');emitMediaState();return}try{state.voice.camera=await navigator.mediaDevices.getUserMedia({video:cameraConstraints(),audio:false});els.cameraBtn.classList.remove('off');if(!state.voice.screen)await setOutgoingVideo(state.voice.camera.getVideoTracks()[0]);updateLocalVideo();emitMediaState()}catch{toast('Não consegui abrir sua câmera.')}}
async function toggleScreen(){if(!state.voice.channelId)return;if(state.voice.screen)return stopScreen();try{const q=resolutionFor(state.media.screenQuality),stream=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:q.width},height:{ideal:q.height},frameRate:{ideal:state.media.screenFps,max:state.media.screenFps}},audio:{restrictOwnAudio:true,suppressLocalAudioPlayback:false}});state.voice.screen=stream;els.screenBtn.classList.add('off');const vt=stream.getVideoTracks()[0];vt.contentHint=state.media.streamPreset==='smooth'?'motion':'detail';vt.onended=stopScreen;await setOutgoingVideo(vt);await syncSystemAudio();updateLocalVideo();emitMediaState();if(!stream.getAudioTracks().length)toast('Tela compartilhada. Esta fonte não forneceu áudio do sistema.',3500)}catch(e){if(e?.name!=='NotAllowedError')toast('Não consegui compartilhar a tela.')}}
async function stopScreen(){if(!state.voice.screen)return;const old=state.voice.screen;state.voice.screen=null;old.getTracks().forEach(t=>t.stop());els.screenBtn.classList.remove('off');await setOutgoingVideo(state.voice.camera?.getVideoTracks()[0]||null);await syncSystemAudio();updateLocalVideo();emitMediaState()}
function streamBitrate(){if(!state.voice.screen)return 2600000;return{economy:2500000,smooth:6000000,quality:8000000,auto:5000000}[state.media.streamPreset]||5000000}
async function tuneSender(sender,kind){try{const p=sender.getParameters();p.encodings=p.encodings?.length?p.encodings:[{}];if(kind==='audio')p.encodings[0].maxBitrate=96000;else{p.encodings[0].maxBitrate=streamBitrate();p.encodings[0].maxFramerate=state.voice.screen?state.media.screenFps:state.media.cameraFps;p.degradationPreference=state.voice.screen&&state.media.streamPreset==='smooth'?'maintain-framerate':'maintain-resolution';try{p.encodings[0].priority=state.voice.screen?'high':'medium';p.encodings[0].networkPriority=state.voice.screen?'high':'medium'}catch{}}await sender.setParameters(p)}catch{}}
async function setOutgoingVideo(track){for(const p of state.voice.peers.values()){let sender=p.pc.getSenders().find(s=>s._bananaVideo);if(sender){await sender.replaceTrack(track);await tuneSender(sender,'video')}else if(track){sender=p.pc.addTrack(track,state.voice.screen||state.voice.camera);sender._bananaVideo=true;await tuneSender(sender,'video');await renegotiate(p)}}}
async function syncSystemAudio(){const track=state.voice.screen?.getAudioTracks()[0]||null;for(const p of state.voice.peers.values()){let sender=p.pc.getSenders().find(s=>s._bananaSystemAudio);if(sender)await sender.replaceTrack(track);else if(track){sender=p.pc.addTrack(track,state.voice.screen);sender._bananaSystemAudio=true;await tuneSender(sender,'audio');await renegotiate(p)}}}
function addLocalTracksToPeer(peer){for(const t of state.voice.localAudio?.getAudioTracks()||[]){const s=peer.pc.addTrack(t,state.voice.localAudio);s._bananaMic=true;tuneSender(s,'audio')}const v=(state.voice.screen||state.voice.camera)?.getVideoTracks()[0];if(v){const s=peer.pc.addTrack(v,state.voice.screen||state.voice.camera);s._bananaVideo=true;tuneSender(s,'video')}const sa=state.voice.screen?.getAudioTracks()[0];if(sa){const s=peer.pc.addTrack(sa,state.voice.screen);s._bananaSystemAudio=true;tuneSender(s,'audio')}}
async function createPeer(socketId,user,initiator,mediaState={}){if(state.voice.peers.has(socketId))return state.voice.peers.get(socketId);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}]});const remoteStream=new MediaStream();const peer={socketId,user,pc,remoteStream,mediaState:mediaState||{},speaking:false,makingOffer:false,ignoreOffer:false,pendingCandidates:[],initiator,_lastBytes:0,_lastStatsAt:0,_disconnectTimer:null};state.voice.peers.set(socketId,peer);addLocalTracksToPeer(peer);pc.onicecandidate=e=>{if(e.candidate)state.socket.emit('webrtc:signal',{targetSocketId:socketId,data:{candidate:e.candidate}})};pc.ontrack=e=>{e.track.enabled=true;if(!remoteStream.getTracks().some(t=>t.id===e.track.id))remoteStream.addTrack(e.track);e.track.onended=()=>addRemoteCard(peer);e.track.onmute=()=>addRemoteCard(peer);e.track.onunmute=()=>addRemoteCard(peer);addRemoteCard(peer)};pc.onconnectionstatechange=()=>{clearTimeout(peer._disconnectTimer);if(pc.connectionState==='failed'){try{pc.restartIce()}catch{}renegotiate(peer)}else if(pc.connectionState==='disconnected'){peer._disconnectTimer=setTimeout(()=>{if(pc.connectionState==='disconnected'){try{pc.restartIce()}catch{}renegotiate(peer)}},4000)}else if(pc.connectionState==='closed')removePeer(socketId);addRemoteCard(peer)};pc.oniceconnectionstatechange=()=>addRemoteCard(peer);pc.onnegotiationneeded=async()=>{if(!peer.initiator&&!pc.remoteDescription)return;await renegotiate(peer)};addRemoteCard(peer);if(initiator)await renegotiate(peer);updateVoiceUI();return peer}
async function renegotiate(peer){if(!peer||peer.pc.signalingState==='closed'||peer.makingOffer||!state.socket?.connected)return;try{peer.makingOffer=true;await peer.pc.setLocalDescription(await peer.pc.createOffer());state.socket.emit('webrtc:signal',{targetSocketId:peer.socketId,data:{description:peer.pc.localDescription}})}catch(e){console.warn('offer',e)}finally{peer.makingOffer=false}}
async function handleSignal(socketId,user,data){let peer=state.voice.peers.get(socketId);if(!peer)peer=await createPeer(socketId,user,false,{});const pc=peer.pc;try{if(data.description){const desc=data.description,collision=desc.type==='offer'&&(peer.makingOffer||pc.signalingState!=='stable'),polite=String(state.socket.id)>String(socketId);peer.ignoreOffer=!polite&&collision;if(peer.ignoreOffer)return;if(collision&&polite)await pc.setLocalDescription({type:'rollback'});await pc.setRemoteDescription(desc);for(const c of peer.pendingCandidates.splice(0)){try{await pc.addIceCandidate(c)}catch{}}if(desc.type==='offer'){await pc.setLocalDescription(await pc.createAnswer());state.socket.emit('webrtc:signal',{targetSocketId:socketId,data:{description:pc.localDescription}})}}else if(data.candidate){if(pc.remoteDescription)await pc.addIceCandidate(data.candidate);else peer.pendingCandidates.push(data.candidate)}}catch(e){console.error('WebRTC signal error',e)}}
function updatePeerMediaState(socketId,mediaState){const p=state.voice.peers.get(socketId);if(!p)return;p.mediaState={...p.mediaState,...mediaState};addRemoteCard(p);applyFocusSharing()}
async function playRemoteAudio(peer,audio,unlock){try{await audio.play();unlock?.classList.add('hidden')}catch{unlock?.classList.remove('hidden')}}
function addRemoteCard(peer){let card=$(`video-${peer.socketId}`);if(!card){card=document.createElement('div');card.className='video-card';card.id=`video-${peer.socketId}`;card.innerHTML='<div class="video-placeholder"><div class="avatar-video"></div></div><video autoplay muted playsinline></video><audio class="remote-audio" autoplay></audio><button class="expand-btn hidden" title="Tela cheia">⛶</button><button class="pin-btn" title="Fixar">📌</button><button class="audio-unlock hidden">🔊 Ativar áudio</button><div class="video-label"></div><div class="peer-stats">conectando…</div><div class="connection-state"></div><div class="peer-volume"><span>🔊</span><input type="range" min="0" max="1" step="0.01"><small></small></div>';els.videoGrid.appendChild(card);wireExpand(card);avatarStyle(card.querySelector('.avatar-video'),peer.user);const slider=card.querySelector('.peer-volume input');slider.value=String(peerVolume(peer.user?.id||''));const out=card.querySelector('.peer-volume small');out.textContent=`${Math.round(Number(slider.value)*100)}%`;slider.addEventListener('input',async e=>{const v=Number(e.target.value);state.media.peerVolumes[peer.user?.id||peer.socketId]=v;savePrefs();out.textContent=`${Math.round(v*100)}%`;await applyOutputDevice(card.querySelector('audio.remote-audio'),peer.user?.id||peer.socketId)});card.querySelector('.audio-unlock').addEventListener('click',()=>playRemoteAudio(peer,card.querySelector('audio.remote-audio'),card.querySelector('.audio-unlock')))}avatarStyle(card.querySelector('.avatar-video'),peer.user);card.querySelector('.video-label').textContent=`${peer.user?.name||'Amigo'}${peer.mediaState?.screen?' · compartilhando tela':peer.mediaState?.muted?' · 🔇':''}`;card.querySelector('.connection-state').textContent=peer.pc.connectionState||'novo';card.classList.toggle('is-sharing',!!peer.mediaState?.screen);card.classList.toggle('speaking',!!peer.speaking&&!peer.mediaState?.muted);const video=card.querySelector('video'),ph=card.querySelector('.video-placeholder'),exp=card.querySelector('.expand-btn'),vTracks=peer.remoteStream.getVideoTracks().filter(t=>t.readyState==='live'),hv=vTracks.length>0;if(hv){const sig=vTracks.map(t=>t.id).join(',');if(video.dataset.sig!==sig){video.srcObject=new MediaStream(vTracks);video.dataset.sig=sig;video.play().catch(()=>{})}}else{video.srcObject=null;video.dataset.sig=''}video.style.display=hv?'block':'none';ph.style.display=hv?'none':'grid';exp.classList.toggle('hidden',!hv);const audio=card.querySelector('audio.remote-audio'),aTracks=peer.remoteStream.getAudioTracks().filter(t=>t.readyState==='live'),aSig=aTracks.map(t=>t.id).join(',');if(audio.dataset.sig!==aSig){audio.srcObject=aTracks.length?new MediaStream(aTracks):null;audio.dataset.sig=aSig}applyOutputDevice(audio,peer.user?.id||peer.socketId);if(aTracks.length)playRemoteAudio(peer,audio,card.querySelector('.audio-unlock'));refreshStatsVisibility();applyFocusSharing()}
function removePeer(socketId){const p=state.voice.peers.get(socketId);if(!p)return;clearTimeout(p._disconnectTimer);try{p.pc.close()}catch{}state.voice.peers.delete(socketId);$(`video-${socketId}`)?.remove();updateVoiceUI()}
function refreshStatsVisibility(){for(const el of document.querySelectorAll('.peer-stats,.connection-state'))el.classList.toggle('hidden',!state.ui.showStats)}
function startPeerStats(){
  clearInterval(state.voice.statsTimer);
  state.voice.statsTimer=setInterval(async()=>{
    let rerenderSidebar=false;
    for(const p of state.voice.peers.values()){
      try{
        const reports=await p.pc.getStats();let rtt=null,lost=0,received=0,bytes=0,remoteVideoLoss=null,remoteVideoRtt=null;
        reports.forEach(r=>{
          if(r.type==='candidate-pair'&&r.state==='succeeded'&&r.currentRoundTripTime!=null)rtt=Math.round(r.currentRoundTripTime*1000);
          if(r.type==='inbound-rtp'&&!r.isRemote){lost+=Math.max(0,r.packetsLost||0);received+=Math.max(0,r.packetsReceived||0);bytes+=Math.max(0,r.bytesReceived||0)}
          if(r.type==='remote-inbound-rtp'&&(r.kind==='video'||r.mediaType==='video')){if(r.fractionLost!=null)remoteVideoLoss=r.fractionLost;if(r.roundTripTime!=null)remoteVideoRtt=r.roundTripTime}
        });
        const now=performance.now();let kbps=null;if(p._lastStatsAt&&bytes>=p._lastBytes)kbps=Math.round(((bytes-p._lastBytes)*8)/(now-p._lastStatsAt));p._lastBytes=bytes;p._lastStatsAt=now;const lossPct=(received+lost)>0?((lost/(received+lost))*100):0;
        if(p.rtt!==rtt){p.rtt=rtt;rerenderSidebar=true}
        const box=$(`video-${p.socketId}`)?.querySelector('.peer-stats');if(box)box.textContent=`${rtt!=null?rtt+' ms':'conectando'}${kbps!=null?` · ${kbps} kbps`:''}${lossPct>.4?` · ${lossPct.toFixed(1)}% perda`:''}`;
        if(state.voice.screen&&state.media.streamPreset==='auto'){
          let target=p._autoBitrate||5000000;
          if((remoteVideoLoss!=null&&remoteVideoLoss>.05)||(remoteVideoRtt!=null&&remoteVideoRtt>.25))target=Math.max(2000000,Math.round(target*.78));
          else if((remoteVideoLoss==null||remoteVideoLoss<.015)&&(remoteVideoRtt==null||remoteVideoRtt<.13))target=Math.min(6500000,Math.round(target*1.08));
          if(Math.abs(target-(p._autoBitrate||0))>150000){p._autoBitrate=target;const sender=p.pc.getSenders().find(s=>s._bananaVideo);if(sender){try{const prm=sender.getParameters();prm.encodings=prm.encodings?.length?prm.encodings:[{}];prm.encodings[0].maxBitrate=target;prm.degradationPreference='balanced';await sender.setParameters(prm)}catch{}}}
        }
      }catch{}
    }
    if(rerenderSidebar)renderChannels();
  },2500)
}
function playEventTone(type){try{const ctx=new AudioContext(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=type==='join'?620:390;gain.gain.setValueAtTime(.05,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.19);setTimeout(()=>ctx.close(),300)}catch{}}

function isEditableTarget(t){return !!t?.closest?.('input,textarea,select,[contenteditable="true"]')}
window.addEventListener('keydown',e=>{if(!state.voice.channelId)return;if(state.ui.pttEnabled&&e.code===state.ui.pttKey&&!isEditableTarget(e.target)){if(!state.voice.pttHeld){state.voice.pttHeld=true;applyMicTrackState();emitMediaState()}e.preventDefault()}});
window.addEventListener('keyup',e=>{if(!state.voice.channelId)return;if(state.ui.pttEnabled&&e.code===state.ui.pttKey){state.voice.pttHeld=false;applyMicTrackState();emitMediaState();e.preventDefault()}});

let pingTimer;function startPing(){clearInterval(pingTimer);pingTimer=setInterval(()=>{if(!state.socket?.connected){els.ping.textContent='offline';return}const sent=performance.now();state.socket.emit('latency:ping',Date.now(),()=>{els.ping.textContent=`${Math.round(performance.now()-sent)} ms`})},3000)}
loadUpdateConfig();
navigator.mediaDevices?.addEventListener?.('devicechange',()=>{if($('micSelect'))$('tabAudio')?.click?.()});
window.addEventListener('beforeunload',()=>{try{if(state.voice.channelId)state.socket.emit('voice:leave')}catch{}});
